+    if Event::has_recent_cipher_access(&cipher.uuid, org_id, act_user_id, event_type, &since, conn).await {
+        return;
+    }
+
+    log_event_impl(event_type, &cipher.uuid, org_id, act_user_id, device_type, Some(event_date), ip, conn).await;
